export type SchoolStatus = 'closed' | 'remote' | 'early-dismissal' | 'conference' | 'term' | 'examination' | 'no-students';
export interface SchoolEntry {
  date: string;
  through?: string;
  name: string;
  status: SchoolStatus;
  audience: readonly string[];
  effect: string;
  weekdaysOnly?: boolean;
  excludeDates?: readonly string[];
}

const ALL = ['NYCPS 全体学生'];
const ELEMENTARY = ['小学', 'Pre-K 中心'];
const MIDDLE = ['初中', 'D75 学校'];
const HIGH = ['高中', 'K–12 学校', '6–12 学校'];
const closed = (date: string, name: string, through?: string): SchoolEntry => ({ date, through, name, status: 'closed', audience: ALL, effect: 'NYCPS 学校关闭；不代表私人、教区、特许学校或所有托育项目采用同一日历。' });
const conference = (date: string, audience: readonly string[], early = false, afternoon = false): SchoolEntry => ({
  date, name: early ? '家长会 · 提前放学' : '家长会', status: early ? 'early-dismissal' : 'conference', audience,
  effect: early ? '适用学段学生提前三小时放学；学校可能调整家长会日期，请以学校通知为准。' : `${afternoon ? '下午及晚间' : '晚间'}家长会；此条未标记提前放学，学校具体安排以学校通知为准。`,
});
const noStudents = (date: string, name: string, audience = ALL): SchoolEntry => ({ date, name, status: 'no-students', audience, effect: '所列学段学生当天不上课；不表示学校建筑关闭或其他学段停课。' });
const term = (date: string, name: string): SchoolEntry => ({ date, name, status: 'term', audience: ALL, effect: 'NYCPS 学年安排；学校个别安排请查学校通知。' });
const exams = (date: string, through: string, excludeDates?: readonly string[]): SchoolEntry => ({ date, through, name: 'Regents 考试', status: 'examination', audience: ['参加 Regents 考试的学生'], effect: '考试安排，不代表全体学生停课；科目与时段以正式考试表为准。', weekdaysOnly: true, excludeDates });

